<?php
$term='%'.mb_substr((string)($_GET['q']??''),0,100).'%';$status=(string)($_GET['status']??'');$payment=(string)($_GET['payment']??'');$courier=trim((string)($_GET['courier']??''));$settlement=(string)($_GET['settlement']??'');
$where='(CAST(o.id AS CHAR) LIKE ? OR o.customer_name LIKE ? OR o.phone LIKE ? OR o.tracking_number LIKE ? OR EXISTS(SELECT 1 FROM order_items i LEFT JOIN products p ON p.id=i.product_id WHERE i.order_id=o.id AND (i.product_name LIKE ? OR p.sku LIKE ?)))';$args=array_fill(0,6,$term);
if($status==='preparing')$where.=" AND o.status IN ('new','preparing')";elseif($status==='shipped')$where.=" AND o.status IN ('shipped','completed')";elseif($status!==''){$where.=' AND o.status=?';$args[]=$status;}
if($payment!==''){$where.=' AND o.payment_status=?';$args[]=$payment;}
if($courier!==''){$where.=' AND o.courier_name=?';$args[]=$courier;}
if($rangeFrom!==''){$where.=' AND o.created_at>=?';$args[]=$rangeFrom;}
if($rangeTo!==''){$where.=' AND o.created_at<?';$args[]=(new DateTimeImmutable($rangeTo))->modify('+1 day')->format('Y-m-d');}
$settled="(o.status IN ('shipped','delivered','handed_over','completed') AND o.inventory_state='deducted' AND o.payment_status='paid')";
if($settlement==='settled')$where.=' AND '.$settled;
if($settlement==='awaiting_dispatch')$where.=" AND o.status IN ('new','preparing') AND o.payment_status='paid'";
if($settlement==='awaiting_payment')$where.=" AND o.status IN ('shipped','delivered','handed_over','completed') AND o.payment_status='unpaid'";
$number=max(1,min(10000,(int)($_GET['p']??1)));$offset=($number-1)*50;$count=(int)query("SELECT COUNT(*) FROM orders o WHERE $where",$args)->fetchColumn();
$rows=query("SELECT o.* FROM orders o WHERE $where ORDER BY o.id DESC LIMIT 50 OFFSET $offset",$args)->fetchAll();
?>
<div class="page-title"><div><p class="eyebrow">PRODAJA I OTPREMA</p><h1>Narudžbe</h1><p>Status otpreme i status naplate prate se odvojeno. Plaćanje ne potvrđuje slanje.</p></div></div>
<nav class="workflow-tabs" aria-label="Dijelovi narudžbi"><?php foreach([''=>'Sve','preparing'=>'U pripremi za slanje','shipped'=>'Poslano','handed_over'=>'Lična predaja','returned'=>'Povrati','cancelled'=>'Otkazano'] as $value=>$label):?><a href="?page=orders&status=<?=$value?>" class="<?=$status===$value?'active':''?>"><?=$label?></a><?php endforeach;?></nav>
<section class="panel"><form method="get" class="admin-filters"><input type="hidden" name="page" value="orders"><input type="hidden" name="status" value="<?=e($status)?>"><div><?php field('q','Broj, kupac, telefon, artikal, SKU ili pošiljka',$_GET['q']??'','text',false);?></div><div><?php selectField('payment','Naplata',[''=>'Sve','unpaid'=>'Nenaplaćeno','paid'=>'Naplaćeno','refunded'=>'Novac vraćen'],$payment);?></div><div><?php $carriers=[''=>'Svi kuriri'];foreach(query("SELECT DISTINCT courier_name FROM orders WHERE courier_name IS NOT NULL AND courier_name<>'' ORDER BY courier_name")->fetchAll(PDO::FETCH_COLUMN) as $c)$carriers[$c]=$c;selectField('courier','Kurirska služba',$carriers,$courier);?></div><div><?php selectField('settlement','Razduženje / obrada',[''=>'Sva stanja','settled'=>'Razduženo i naplaćeno','awaiting_dispatch'=>'Naplaćeno, čeka otpremu','awaiting_payment'=>'Otpremljeno, čeka naplatu'],$settlement);?></div><div><?php field('from','Datum narudžbe od',$rangeFrom,'date',false);?></div><div><?php field('to','Datum narudžbe do',$rangeTo,'date',false);?></div><button>Primijeni filter</button></form><div class="table-heading"><h2>Registar narudžbi</h2><span><?=$count?> rezultata</span></div><div class="table-scroll"><table><thead><tr><th>Narudžba / kupac</th><th>Ukupno</th><th>Otprema</th><th>Naplata</th><th>Kurir / pošiljka</th><th>Razduženje</th><th></th></tr></thead><tbody><?php foreach($rows as $o):?><tr><td><a href="?page=order&id=<?=$o['id']?>">#<?=$o['id']?> · <?=e($o['customer_name'])?></a><small class="cell-note"><?=e($o['created_at'])?></small></td><td class="numeric"><?=money((float)$o['total'])?></td><td><span class="status-badge status-<?=e($o['status'])?>"><?=e(orderStatus($o['status']))?></span></td><td><span class="status-badge status-<?=e($o['payment_status'])?>"><?=e(paymentLabel($o['payment_status']))?></span></td><td><?=e($o['dispatch_method']==='personal'?'Lična predaja':($o['courier_name']??'Nije evidentiran'))?><small class="cell-note"><?=e((string)$o['tracking_number'])?></small></td><td><?=isOrderSettled($o)?'Razduženo i naplaćeno':($o['inventory_state']==='reserved'?'Rezervisano na lageru':($o['inventory_state']==='deducted'?'Izvan lagera':($o['inventory_state']==='released'?'Vraćeno na lager':'Stari zapis · provjera')))?></td><td><a class="table-action" href="?page=order&id=<?=$o['id']?>">Obradi ↗</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="table-empty">Nema narudžbi za odabrane filtere.</td></tr><?php endif;?></tbody></table></div><div class="list-pagination"><span>Stranica <?=$number?> / <?=max(1,(int)ceil($count/50))?></span><?php foreach([-1=>'← Prethodna',1=>'Sljedeća →'] as $delta=>$label):if(($delta<0&&$number>1)||($delta>0&&$offset+50<$count)):?><a href="?<?=e(http_build_query(array_merge($_GET,['p'=>$number+$delta])))?>"><?=$label?></a><?php endif;endforeach;?></div></section>
